window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[198]={"id":"198","numero":198,"titre":"Arthropathie microcristalline","objectifs":[{"id":"198-1","rang":"A","rubrique":"Définition","titre":"Connaître les trois principaux microcristaux impliqués en pathologie humaine","contenu":"<div class=\"callout callout-info\"><strong>L'essentiel.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">arthropathies microcristallines</span> sont des dépôts <span class=\"kw-def\">intra-articulaires</span> ou <span class=\"kw-def\">péri-articulaires</span> de microcristaux, longtemps asymptomatiques puis responsables d'<span class=\"kw-clinique\">accès inflammatoires aigus</span> ou d'<span class=\"kw-clinique\">arthropathies chroniques</span>. C'est l'archétype de l'inflammation aiguë en pathologie humaine.</div>\n\n      <table >\n        <thead><tr><th>Microcristal</th><th>Maladie</th><th>Microscopie optique</th><th><span class=\"kw-def\">Terrain</span> typique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Urate de sodium</strong></span> (UMS, urate monosodique)</td>\n            <td><span class=\"kw-def\">Goutte</span></td>\n            <td>Visibles (microscopiques)</td>\n            <td><span class=\"kw-etio\">Homme &gt; 35 ans</span>, surpoids</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Pyrophosphate de calcium</strong></span> (PPC), cristal <span class=\"kw-def\">calcique</span></td>\n            <td><span class=\"kw-def\">Chondrocalcinose</span> (pseudo-goutte)</td>\n            <td>Visibles (microscopiques)</td>\n            <td><span class=\"kw-etio\">Sujet âgé</span>, prédominance féminine</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Phosphate de calcium / apatite</strong></span>, cristal <span class=\"kw-def\">calcique</span></td>\n            <td><span class=\"kw-def\">Rhumatisme apatitique</span></td>\n            <td><span class=\"kw-alerte\">Non visibles</span> (submicroscopiques)</td>\n            <td><span class=\"kw-etio\">Femme jeune</span> (<span class=\"kw-chiffre\">30-50 ans</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><span class=\"kw-clinique\">Les</span> dépôts d'<span class=\"kw-def\">apatite</span> sont habituellement <strong>péri-articulaires</strong> et <span class=\"kw-imagerie\">radio-opaques</span> ; ils ne sont identifiables qu'après <span class=\"kw-bio\">coloration au rouge d'alizarine</span>.</p>\n\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">cristaux d'acide urique</span> (et non d'urate de sodium) n'existent que dans les <span class=\"kw-clinique\">voies urinaires</span> — jamais dans l'articulation.</div>","frequence":0},{"id":"198-2","rang":"A","rubrique":"Définition","titre":"Connaître la valeur seuil de l’hyperuricémie","contenu":"<div class=\"callout callout-warn\"><strong>À connaître par cœur.</strong> <span class=\"kw-bio\">Hyperuricémie</span> = <span class=\"kw-bio\">uricémie</span> <span class=\"kw-chiffre\">&gt; 360 µmol/L</span> (soit <span class=\"kw-chiffre\">60 mg/L</span>).</div>\n\n      <ul>\n        <li>Cette valeur correspond au <span class=\"kw-def\">seuil de saturation du plasma en urate de sodium</span> à <span class=\"kw-chiffre\">35 °C</span> (température des extrémités).</li>\n        <li>C'est aussi l'<span class=\"kw-bio\">uricémie « cible »</span> du traitement : la <span class=\"kw-def\">cristallisation</span> est <strong>réversible</strong> — abaisser l'<span class=\"kw-bio\">uricémie</span> sous ce seuil permet la <span class=\"kw-clinique\">dissolution des cristaux</span>.</li>\n        <li>L'<span class=\"kw-bio\">hyperuricémie</span> est une cause <strong>nécessaire mais non suffisante</strong> : seuls <span class=\"kw-chiffre\">10 à 15 %</span> des sujets hyperuricémiques développent une <span class=\"kw-def\">goutte</span>.</li>\n        <li>Le risque de <span class=\"kw-def\">goutte</span> augmente avec la <strong>durée</strong> et l'<strong>intensité</strong> de l'hyperuricémie.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">L'<span class=\"kw-bio\">hyperuricémie asymptomatique</span> ne se traite <strong>pas</strong> par un <span class=\"kw-ttt\">hypo-uricémiant</span> (seules mesures hygiéno-diététiques). Voir <em>Prise en charge</em>.</div>","frequence":0},{"id":"198-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la réaction inflammatoire aiguë et le phénomène de cristallisation","contenu":"<p>Dans la goutte, la cristallisation dépend du <strong><span class=\"kw-bio\">pH</span></strong> et du <strong>site</strong> :</p>\n\n      <table >\n        <thead><tr><th>Site</th><th>pH</th><th>Cristallisation</th><th>Conséquences</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Tissus / articulations</span></td>\n            <td><span class=\"kw-chiffre\">pH neutre</span></td>\n            <td>Équilibre déplacé vers l'<span class=\"kw-def\">urate de sodium</span> ; dépôts cristallins <strong>très lents</strong> (maladie de surcharge)</td>\n            <td>\n              <strong>Accès aigu :</strong> libération des microcristaux d'<span class=\"kw-def\">UMS</span> → activation de l'<span class=\"kw-bio\">inflammasome NLRP3</span><br>\n              <strong>Tophus :</strong> dépôts tissulaires d'UMS en amas constitués avec le temps<br>\n              <strong>Arthropathie chronique :</strong> tophus intra-articulaires et osseux\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Voies urinaires</span></td>\n            <td><span class=\"kw-chiffre\">pH acide &lt; 6</span></td>\n            <td>Formation de <span class=\"kw-clinique\">lithiases d'acide urique</span>, cristallisation <strong>très rapide</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Colique néphrétique</span> en aigu<br>\n              <span class=\"kw-alerte\">Néphropathie uratique</span> si chronicisation\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p>L'inflammation aiguë déclenchée par <span class=\"kw-clinique\">les</span> cristaux est <span class=\"kw-clinique\">brutale</span> (maximum en <span class=\"kw-chiffre\">&lt; 24 h</span>) et <strong>résolutive spontanément</strong>. La voie commune est l'<span class=\"kw-bio\">inflammasome NLRP3</span> → <span class=\"kw-bio\">IL-1β</span> (cible des inhibiteurs d'IL-1).</p>\n\n      <div class=\"callout callout-info\"><strong>Origine de l'hyperuricémie.</strong> Dans <span class=\"kw-chiffre\">90 %</span> des gouttes : <span class=\"kw-etio\">défaut d'élimination rénale et/ou intestinale</span> de l'acide urique (rarement un excès de production).</div>","frequence":0},{"id":"198-4","rang":"B","rubrique":"Contenu multimédia","titre":"Radiographie de poignet : calcification du ligament triangulaire du carpe","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/198/rx-poignet-chondrocalcinose.png\" alt=\"Radiographie de poignet de face — calcification du ligament triangulaire du carpe au cours d'une chondrocalcinose\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie du poignet de face</span> : <span class=\"kw-imagerie\">calcification du ligament triangulaire du carpe</span> (fibrocartilage), associée à un <span class=\"kw-imagerie\">pincement articulaire</span> (rhizarthrose et arthrose scapho-trapézoïdienne) — <span class=\"kw-def\">rhumatisme à cristaux de pyrophosphate de calcium</span> (chondrocalcinose articulaire). Source : banque imagerie EDN, item 198.</figcaption>\n      </figure>\n\n      <ul>\n        <li>La <span class=\"kw-imagerie\">calcification du ligament triangulaire du carpe</span> est l'un des sites <strong>fibro-cartilagineux</strong> <span class=\"kw-clinique\">les</span> plus évocateurs de <span class=\"kw-def\">chondrocalcinose</span>.</li>\n        <li>Moyen mnémo des dépôts fibro-cartilagineux — <strong>PSG</strong> : <span class=\"kw-imagerie\">Poignet</span> · <span class=\"kw-imagerie\">Symphyse pubienne</span> · <span class=\"kw-imagerie\">Genou</span>.</li>\n        <li>On recherche aussi des <span class=\"kw-imagerie\">calcifications des cartilages intracarpiens</span> et un <span class=\"kw-imagerie\">pincement scapho-trapézoïdien</span>.</li>\n        <li>La <span class=\"kw-imagerie\">TDM cérébrale ou cervicale</span> peut révéler une <span class=\"kw-imagerie\">calcification arciforme du ligament transverse de l'atlas</span> (<span class=\"kw-clinique\">syndrome de la</span> dent couronnée).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">Clichés toujours <strong>bilatéraux et comparatifs</strong> (<span class=\"kw-imagerie\">mains et poignets de face</span>) pour apprécier le caractère diffus des dépôts de <span class=\"kw-def\">PPC</span>.</div>","frequence":0},{"id":"198-5","rang":"B","rubrique":"Contenu multimédia","titre":"Radiographie du genou : calcification méniscale, calcification cartilagineuse","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/198/rx-genou-chondrocalcinose.png\" alt=\"Radiographie du genou de face — calcifications méniscales et des interlignes fémoro-tibiaux au cours d'une chondrocalcinose\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie du genou de face</span> : <span class=\"kw-imagerie\">calcifications des interlignes fémoro-tibiaux</span> = <span class=\"kw-imagerie\">calcifications méniscales</span> — <span class=\"kw-def\">chondrocalcinose articulaire</span>. Source : banque imagerie EDN, item 198.</figcaption>\n      </figure>\n\n      <ul>\n        <li>Le <span class=\"kw-imagerie\">genou</span> est le site le plus fréquent : calcifications méniscales dans <span class=\"kw-chiffre\">90 %</span> des chondrocalcinoses, sous forme d'<span class=\"kw-imagerie\">opacités triangulaires à base externe</span>.</li>\n        <li>Calcification du <strong>cartilage hyalin</strong> : <span class=\"kw-imagerie\">opacités linéaires</span> restant à distance et <strong>parallèles</strong> à l'os sous-chondral.</li>\n        <li>Clichés du genou : <span class=\"kw-imagerie\">face debout, en schuss, profil, défilés fémoro-patellaires</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Objectif très tombable (⭐⭐⭐).</strong> Savoir reconnaître <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">calcifications méniscales</span> du genou comme signature radiologique de la chondrocalcinose.</div>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/chondrocalcinosis","label":"Radiopaedia : Chondrocalcinosis"}]},{"id":"198-6","rang":"B","rubrique":"Contenu multimédia","titre":"Radiographie de bassin : calcifications de la symphyse pubienne et des cartilages fémoraux","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/198/rx-bassin-chondrocalcinose.png\" alt=\"Radiographie de bassin de face centrée sur la symphyse pubienne — calcification de la symphyse au cours d'une chondrocalcinose\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie du bassin de face</span>, centrée sur la symphyse pubienne : <span class=\"kw-imagerie\">calcification linéaire verticale de la symphyse pubienne</span> — <span class=\"kw-def\">chondrocalcinose articulaire</span>. Source : banque imagerie EDN, item 198.</figcaption>\n      </figure>\n\n      <ul>\n        <li>La <span class=\"kw-imagerie\">symphyse pubienne</span> est le 3ᵉ site fibro-cartilagineux du moyen mnémo <strong>PSG</strong> : <span class=\"kw-imagerie\">calcification linéaire verticale</span>.</li>\n        <li>Sur le cartilage hyalin : dépôts de la <span class=\"kw-imagerie\">tête fémorale</span> sous forme d'<span class=\"kw-imagerie\">opacités linéaires parallèles à l'os sous-chondral</span>.</li>\n        <li>Cliché du bassin : <span class=\"kw-imagerie\">debout, de face</span>, centré sur la symphyse.</li>\n        <li>Ces <span class=\"kw-imagerie\">calcifications</span> signent un <span class=\"kw-def\">rhumatisme à pyrophosphate de calcium</span> (<span class=\"kw-def\">chondrocalcinose</span>).</li>\n      </ul>","frequence":0},{"id":"198-7","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence de la goutte en France","contenu":"<div class=\"callout callout-warn\"><strong>Chiffre clé.</strong> <span class=\"kw-def\">Prévalence</span> de la <span class=\"kw-def\">goutte</span> en France ≈ <span class=\"kw-chiffre\">1 %</span>.</div>\n\n      <ul>\n        <li>C'est le <span class=\"kw-def\">rhumatisme inflammatoire intermittent le plus fréquent</span> en France.</li>\n        <li>Prédominance chez l'<span class=\"kw-etio\">homme adulte</span> ; la <span class=\"kw-etio\">femme</span> est protégée jusqu'à la <span class=\"kw-etio\">ménopause</span>.</li>\n        <li>Le pic d'<span class=\"kw-def\">incidence</span> se situe vers <span class=\"kw-chiffre\">35-40 ans</span> chez l'homme.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">La <span class=\"kw-def\">goutte</span> est le plus fréquent des <span class=\"kw-def\">rhumatismes microcristallins</span> ; la <span class=\"kw-def\">chondrocalcinose</span> devient prédominante chez le <span class=\"kw-etio\">sujet âgé</span>.</div>","frequence":0},{"id":"198-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la description d’un accès aigu microcristallin","contenu":"<p><span class=\"kw-clinique\">Les</span> caractéristiques sémiologiques d'un <span class=\"kw-def\">accès aigu microcristallin</span> typique :</p>\n      <ul>\n        <li><strong>Début brutal</strong> : maximum des symptômes en <span class=\"kw-chiffre\">&lt; 24 h</span>.</li>\n        <li><strong>Douleur intense</strong> : <span class=\"kw-clinique\">EVA / EN ≥ 7/10</span>.</li>\n        <li><strong>Inflammation locale forte</strong> : <span class=\"kw-clinique\">rougeur « rouge pivoine »</span>, <span class=\"kw-clinique\">gonflement</span>, chaleur.</li>\n        <li><strong>Résolution spontanée</strong> (<span class=\"kw-chiffre\">jours à semaines</span>) avec restauration <em>ad integrum</em> de l'articulation au début de la maladie.</li>\n        <li>Résolution <strong>accélérée</strong> par <span class=\"kw-clinique\">les</span> anti-inflammatoires (ex. <span class=\"kw-ttt\">colchicine</span> débutée tôt dans la goutte).</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong>Universel.</strong> Cette description vaut pour l'accès de <span class=\"kw-def\">goutte</span> mais aussi pour <span class=\"kw-clinique\">les</span> autres crises microcristallines (<span class=\"kw-def\">PPC</span>, <span class=\"kw-def\">apatite</span>).</div>\n\n      <p>L'inflammation peut s'accompagner de <span class=\"kw-clinique\">signes généraux</span> (<span class=\"kw-clinique\">fièvre</span>, voire <span class=\"kw-clinique\">frissons</span>) et d'un <span class=\"kw-bio\">syndrome inflammatoire biologique</span> (<span class=\"kw-bio\">CRP</span> élevée, <span class=\"kw-bio\">hyperleucocytose</span>) — d'où la nécessité d'éliminer une infection (voir <em>Identifier une <span class=\"kw-alerte\">urgence</span></em>).</p>","frequence":0},{"id":"198-9","rang":"B","rubrique":"Epidémiologie","titre":"Connaître le terrain, les comorbidités et les facteurs déclenchants d’une crise de goutte","contenu":"<p><strong><span class=\"kw-def\">Terrain</span> et comorbidités</strong> de la goutte :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Homme &gt; 35 ans</span> ou <span class=\"kw-etio\">femme ménopausée</span>.</li>\n        <li><span class=\"kw-etio\">Contexte familial</span> : maladie à forte composante <span class=\"kw-etio\">génétique</span> (polygénique le plus souvent).</li>\n        <li><span class=\"kw-etio\">Syndrome métabolique</span> : <span class=\"kw-etio\">obésité</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">HTA</span>, <span class=\"kw-etio\">dyslipidémie</span> → <strong>fort risque cardiovasculaire</strong>.</li>\n        <li><span class=\"kw-etio\">Insuffisance rénale chronique</span>, <span class=\"kw-etio\">transplantation d'organe</span>.</li>\n        <li><span class=\"kw-ttt\">Diurétiques</span> de l'anse et thiazidiques, <span class=\"kw-ttt\">ciclosporine</span>.</li>\n      </ul>\n\n      <p><strong>Facteurs déclenchants</strong> d'une crise :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Traumatisme</span>, contexte <span class=\"kw-etio\">post-opératoire</span>.</li>\n        <li><span class=\"kw-etio\">Infarctus</span> ou <span class=\"kw-etio\">infection</span> à distance.</li>\n        <li><span class=\"kw-alerte\">Mise en route d'un traitement hypo-uricémiant</span> ⚠️ (variation brutale de l'<span class=\"kw-bio\">uricémie</span>).</li>\n        <li><span class=\"kw-etio\">Écarts nutritionnels</span> — moyen mnémo <strong>BAS</strong> : <span class=\"kw-etio\">Bières</span> (riches en purines, même sans <span class=\"kw-etio\">alcool</span>) · <span class=\"kw-etio\">Alcools forts</span> · <span class=\"kw-etio\">Sodas sucrés</span> riches en fructose.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Piège thérapeutique.</strong> Débuter un hypo-uricémiant <span class=\"kw-alerte\">déclenche</span> des crises : d'où la couverture par <span class=\"kw-ttt\">colchicine</span> pendant <span class=\"kw-chiffre\">≥ 6 mois</span> en début de traitement.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> · 224 — HTA · 223 — Dyslipidémie · 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":0},{"id":"198-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une crise de goutte et d’identification des situations nécessitant un avis spécialisé","contenu":"<p>Le diagnostic repose sur la mise en évidence des <strong>microcristaux</strong>, complétée par un <strong>faisceau d'arguments</strong> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Microcristaux d'UMS</span> dans le <span class=\"kw-bio\">liquide articulaire</span> ou dans un <span class=\"kw-clinique\">tophus</span> = <strong>examen de référence</strong> (<span class=\"kw-alerte\">pathognomonique</span>).</li>\n        <li><span class=\"kw-etio\">Terrain</span> évocateur + <span class=\"kw-clinique\">accès aigu typique</span> (rouge pivoine, &lt;<span class=\"kw-chiffre\"> 24 h</span>, MTP du gros orteil).</li>\n        <li><span class=\"kw-bio\">Uricémie</span> <span class=\"kw-chiffre\">&gt; 360 µmol/L</span> — mais <span class=\"kw-alerte\">peut être normale pendant l'accès</span> : la recontrôler <span class=\"kw-chiffre\">≈ 15 jours après</span> la crise.</li>\n        <li><span class=\"kw-imagerie\">Échographie articulaire</span> : signe du <span class=\"kw-imagerie\">« double contour »</span>, utile au diagnostic (<span class=\"kw-def\">classification</span> EULAR/<span class=\"kw-alerte\">ACR</span>).</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong>Quand demander un avis spécialisé (rhumatologue) ?</strong>\n        <ul>\n          <li>Goutte <span class=\"kw-alerte\">précoce &lt; 35 ans</span> (recherche de maladie <span class=\"kw-etio\">génétique</span> ou rénale).</li>\n          <li>Goutte <span class=\"kw-clinique\">polyarticulaire</span>, <span class=\"kw-clinique\">tophacée</span> ou avec <span class=\"kw-clinique\">dactylite</span>.</li>\n          <li>Goutte sur <span class=\"kw-etio\">insuffisance rénale chronique</span> (<span class=\"kw-chiffre\">DFGe &lt; 60 mL/min</span>).</li>\n          <li>Goutte sur <span class=\"kw-etio\">insuffisance cardiaque</span> ou coronaire instable.</li>\n          <li>Goutte <strong>difficile à traiter</strong> (inefficacité, <span class=\"kw-ci\">intolérance</span> / CI à <span class=\"kw-ttt\">colchicine</span>, <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">corticoïdes</span>).</li>\n          <li><span class=\"kw-ci\">Antécédent d'allergie à l'allopurinol</span> avant mise en route du fébuxostat.</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 200 — Douleur/épanchement articulaire - Arthrite récente</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/gout","label":"Radiopaedia : Gout"}]},{"id":"198-11","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les modalités d’exclusion d’une une arthrite septique","contenu":"<div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> à éliminer en priorité.</strong> L'<span class=\"kw-alerte\">arthrite septique</span> est le <strong>principal <span class=\"kw-def\">diagnostic différentiel</span></strong> d'un accès microcristallin : mono-arthrite aiguë fébrile à <span class=\"kw-ci\">ne jamais</span> négliger.</div>\n\n      <p>Pourquoi le piège — l'inflammation cristalline donne :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre</span>, voire <span class=\"kw-clinique\">frissons</span>.</li>\n        <li><span class=\"kw-bio\">Syndrome inflammatoire biologique</span> : <span class=\"kw-bio\">CRP</span> élevée, <span class=\"kw-bio\">VS</span>, <span class=\"kw-bio\">hyperleucocytose</span>.</li>\n      </ul>\n      <p>… ce qui peut faire évoquer à tort une <span class=\"kw-alerte\">arthrite septique</span>, un <span class=\"kw-alerte\">abcès</span> ou une <span class=\"kw-alerte\">cellulite</span> infectieuse.</p>\n\n      <p><strong>Modalités d'exclusion :</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">Ponction articulaire</span> avec <span class=\"kw-bio\">examen bactériologique systématique</span> du liquide synovial.</li>\n        <li>Diagnostic d'arthrite microcristalline retenu si : présence de <span class=\"kw-bio\">microcristaux</span> ET <span class=\"kw-bio\">bactériologie négative</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Nuance.</strong> Cristaux et infection ne s'excluent pas : une <span class=\"kw-etio\">infection</span> est un facteur déclenchant classique d'accès de goutte ou de pseudo-goutte → une <span class=\"kw-alerte\">association</span> est possible.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 156 — Infection ostéo-articulaire · 200 — Douleur/épanchement articulaire - Arthrite récente</em></p>","frequence":0},{"id":"198-12","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les formes polyarticulaires ou oligoarticulaires","contenu":"<ul>\n        <li><strong><span class=\"kw-def\">Goutte</span></strong> : le plus souvent <span class=\"kw-clinique\">monoarthrite</span>, mais des <span class=\"kw-clinique\">oligoarthrites</span> ou <span class=\"kw-clinique\">polyarthrites goutteuses</span> sont possibles (surtout goutte ancienne / <span class=\"kw-clinique\">tophacée</span>).</li>\n        <li><strong><span class=\"kw-def\">Chondrocalcinose (PPC)</span></strong> : arthrite aiguë <span class=\"kw-clinique\">mono-</span> ou <span class=\"kw-clinique\">oligoarticulaire</span> (voire <span class=\"kw-clinique\">polyarticulaire</span>), volontiers <span class=\"kw-clinique\">récidivante</span> ; topographie <span class=\"kw-clinique\">genou</span>, <span class=\"kw-clinique\">poignet</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>À distinguer (piège diagnostique).</strong> La <span class=\"kw-def\">polyarthrite chronique à PPC</span> peut devenir <strong>bilatérale et symétrique</strong> avec pincement des interlignes, évoquant faussement une <span class=\"kw-alerte\">polyarthrite rhumatoïde</span> (forme « pseudo-rhumatoïde »).</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 196 — <span class=\"kw-clinique\">Polyarthrite rhumatoïde</span></em></p>","frequence":0},{"id":"198-13","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques d’un liquide inflammatoire","contenu":"<p>Caractéristiques d'un <span class=\"kw-bio\">liquide synovial inflammatoire</span> microcristallin :</p>\n      <ul>\n        <li><strong>Aspect</strong> : <span class=\"kw-bio\">trouble</span>, fluide (peu visqueux).</li>\n        <li><strong>Cellularité</strong> : <span class=\"kw-chiffre\">&gt; 2 000 cellules/mm³</span> (parfois <span class=\"kw-chiffre\">&gt; 100 000/mm³</span>), à prédominance de <span class=\"kw-bio\">polynucléaires neutrophiles</span>.</li>\n        <li><strong>Protéines</strong> : <span class=\"kw-chiffre\">&gt; 40 g/L</span>.</li>\n        <li><strong>Bactériologie</strong> : <span class=\"kw-bio\">négative</span> (recherchée systématiquement).</li>\n        <li><strong>Microcristaux</strong> : mise en évidence d'<span class=\"kw-bio\">UMS</span> ou de <span class=\"kw-bio\">PPC</span>.</li>\n      </ul>\n\n      <table >\n        <thead><tr><th>Critère</th><th>UMS (goutte)</th><th>PPC (chondrocalcinose)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Forme</strong></td>\n            <td><span class=\"kw-bio\">Fins, allongés en aiguille, pointus</span></td>\n            <td><span class=\"kw-bio\">Carrés ou rectangulaires, courts</span></td>\n          </tr>\n          <tr>\n            <td><strong>Lumière polarisée</strong></td>\n            <td><span class=\"kw-bio\">Fortement biréfringents</span></td>\n            <td><span class=\"kw-bio\">Peu ou pas biréfringents</span></td>\n          </tr>\n          <tr>\n            <td><strong>Sensibilité</strong></td>\n            <td>Sensibles à l'<span class=\"kw-bio\">uricase</span></td>\n            <td>Sensibles à l'<span class=\"kw-bio\">EDTA</span></td>\n          </tr>\n          <tr>\n            <td><strong>Résistance</strong></td>\n            <td>Résistants à l'<span class=\"kw-bio\">EDTA</span></td>\n            <td>Résistants à l'<span class=\"kw-bio\">uricase</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><span class=\"kw-clinique\">Les</span> microcristaux doivent être recherchés sur <strong>tout</strong> liquide synovial d'arthrite indifférenciée ou récidivante inclassée. À l'inverse, les cristaux d'<span class=\"kw-def\">apatite</span> sont <span class=\"kw-alerte\">submicroscopiques</span> et invisibles en lumière polarisée.</div>","frequence":0},{"id":"198-14","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un tophus cliniquement décelable (typique)","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/198/tophus-localisations-typiques.png\" alt=\"Photographies de tophus goutteux — hélix de l'oreille, bursite olécrânienne du coude, pulpe des doigts\" loading=\"lazy\">\n        <figcaption>Exemples de <span class=\"kw-clinique\">tophus</span> : <span class=\"kw-clinique\">nodule</span> sous-cutané ferme, chamois/crayeux par transparence. Localisations typiques — <span class=\"kw-clinique\">hélix de l'oreille</span> (A), <span class=\"kw-clinique\">coude / bursite olécrânienne</span> (B), <span class=\"kw-clinique\">pulpe des doigts</span> (C, D). Source : fiche source EDN item 198 — Goutte.</figcaption>\n      </figure>\n\n      <p>Le <span class=\"kw-def\">tophus</span> est un amas de cristaux d'<span class=\"kw-def\">UMS</span> cerclé d'une couronne cellulaire <span class=\"kw-etio\">inflammatoire</span> (aspect pseudo-granulomateux). Localisations à connaître :</p>\n      <ul>\n        <li>Autour des <span class=\"kw-clinique\">articulations atteintes</span> ++.</li>\n        <li><span class=\"kw-clinique\">Pavillon / hélix de l'oreille</span>.</li>\n        <li><span class=\"kw-clinique\">Coude</span> (bursite olécrânienne), tendons (<span class=\"kw-clinique\">calcanéen</span>, patellaire).</li>\n        <li><span class=\"kw-clinique\">Articulations IPD</span> ou pulpe des doigts (patients sous <span class=\"kw-ttt\">diurétiques</span>).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">Le tophus peut <strong>s'enflammer</strong> et s'aboucher à la peau, laissant sourdre un <span class=\"kw-clinique\">liquide crayeux</span> ; il est responsable d'un <span class=\"kw-clinique\">handicap fonctionnel</span> par <span class=\"kw-clinique\">les</span> déformations.</div>","frequence":0},{"id":"198-15","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les deux examens biologiques indispensables à visée diagnostique dans la goutte","contenu":"<div class=\"callout callout-warn\"><strong><span class=\"kw-clinique\">Les</span> deux examens indispensables.</strong>\n        <ul>\n          <li><strong>1.</strong> <span class=\"kw-bio\">Uricémie</span> — hyperuricémie <span class=\"kw-chiffre\">&gt; 360 µmol/L</span> (<span class=\"kw-chiffre\">60 mg/L</span>) ; <span class=\"kw-alerte\">peut être normale en crise</span> → recontrôle à <span class=\"kw-chiffre\">15 jours</span>.</li>\n          <li><strong>2.</strong> <span class=\"kw-bio\">Analyse du liquide articulaire</span> — mise en évidence des <span class=\"kw-bio\">microcristaux d'UMS</span> (<span class=\"kw-alerte\">pathognomonique</span>), <span class=\"kw-bio\">liquide inflammatoire</span>, <span class=\"kw-bio\">bactériologie négative</span>.</li>\n        </ul>\n      </div>\n\n      <p>À visée <span class=\"kw-etio\">étiologique</span> et préthérapeutique (non « diagnostiques » mais systématiques) :</p>\n      <ul>\n        <li><span class=\"kw-bio\">NFS-plaquettes</span> (<span class=\"kw-etio\">hémopathie chronique</span>).</li>\n        <li><span class=\"kw-bio\">Créatininémie</span> + calcul du <span class=\"kw-bio\">DFGe</span> (<span class=\"kw-etio\">insuffisance rénale</span>, choix du THU).</li>\n        <li><span class=\"kw-bio\">Bilan lipidique</span> (<span class=\"kw-etio\">risque cardiovasculaire</span> associé).</li>\n      </ul>","frequence":0},{"id":"198-16","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le risque de surmortalité de la goutte non traitée","contenu":"<div class=\"callout callout-danger\"><strong><span class=\"kw-def\">Pronostic</span>.</strong> La <span class=\"kw-def\">goutte</span> non traitée s'accompagne d'une <span class=\"kw-alerte\">surmortalité cardiovasculaire</span> : le patient goutteux est à considérer comme à <strong>fort risque CV</strong> (<span class=\"kw-etio\">syndrome métabolique</span> fréquemment associé).</div>\n\n      <ul>\n        <li>La <span class=\"kw-def\">goutte</span> est un <span class=\"kw-etio\">marqueur de risque cardiovasculaire</span> à part entière (association <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">HTA</span>, <span class=\"kw-etio\">obésité</span>).</li>\n        <li>Un <span class=\"kw-ttt\">traitement hypo-uricémiant</span> amenant l'<span class=\"kw-bio\">uricémie</span> à la <span class=\"kw-bio\">cible</span> réduit la <strong><span class=\"kw-def\">mortalité</span> CV de ≈ <span class=\"kw-chiffre\">50 %</span> à <span class=\"kw-chiffre\">15 ans</span></strong>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> · 223 — Dyslipidémie · 224 — HTA</em></p>","frequence":0},{"id":"198-17","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les différences de terrain entre goutte, arthropathie à pyrophosphate de calcium (PPCa) et calcification apatitique","contenu":"<table >\n        <thead><tr><th></th><th>Goutte (UMS)</th><th>Chondrocalcinose (PPC)</th><th>Rhumatisme apatitique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td><span class=\"kw-etio\">Homme &gt; 35 ans</span>, surpoids, CV, IRC, <span class=\"kw-etio\">diabète</span></td>\n            <td><span class=\"kw-etio\">Sujet âgé</span>, prédominance <span class=\"kw-etio\">féminine</span> (diminue avec l'âge)</td>\n            <td><span class=\"kw-etio\">Femme plus jeune</span> (<span class=\"kw-chiffre\">30-50 ans</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Cristal</strong></td>\n            <td><span class=\"kw-def\">Urate de sodium</span></td>\n            <td><span class=\"kw-def\">Pyrophosphate de calcium</span></td>\n            <td><span class=\"kw-def\">Phosphate de calcium / apatite</span></td>\n          </tr>\n          <tr>\n            <td><strong>Microscopie optique</strong></td>\n            <td>Visibles</td>\n            <td>Visibles</td>\n            <td><span class=\"kw-alerte\">Non visibles</span> (submicroscopiques)</td>\n          </tr>\n          <tr>\n            <td><strong>Localisations</strong></td>\n            <td><span class=\"kw-clinique\">MTP du gros orteil</span>, pied (tarse, cheville)</td>\n            <td><span class=\"kw-clinique\">Genou</span>, <span class=\"kw-clinique\">poignet</span></td>\n            <td><span class=\"kw-clinique\">Péri-articulaire</span> : épaule (coiffe), main, poignets</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Radiographie</span></strong></td>\n            <td>Normale au début (± arthrose)</td>\n            <td><span class=\"kw-imagerie\">Calcifications intra-articulaires</span></td>\n            <td><span class=\"kw-imagerie\">Calcifications péri-articulaires</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">cristaux d'apatite</span> siègent surtout en <strong>péri-articulaire</strong> (tendons, capsules, bourses) et sont <span class=\"kw-imagerie\">radio-opaques</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 268 — Hypercalcémie · 219 — Pathologie du fer</em></p>","frequence":0},{"id":"198-18","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge d’une crise aiguë de goutte","contenu":"<div class=\"callout callout-info\"><strong>Principe.</strong> Traiter la crise <strong>le plus tôt possible</strong>. Le choix dépend des <span class=\"kw-etio\">comorbidités</span> (CV, <span class=\"kw-chiffre\">DFGe &lt; 60</span>, <span class=\"kw-etio\">diabète</span>, ulcère, infection), des interactions et du nombre d'articulations. Le traitement de la crise <strong>ne suffit pas</strong> à traiter la maladie.</div>\n\n      <table >\n        <thead><tr><th>Moyen</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Colchicine</strong></span></td>\n            <td>À initier idéalement <span class=\"kw-chiffre\">&lt; 12 h</span> ; <strong>faibles doses</strong> aussi efficaces et moins toxiques que <span class=\"kw-clinique\">les</span> fortes doses.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>AINS</strong></span></td>\n            <td><span class=\"kw-ttt\">Naproxène</span> per os (meilleur profil CV) ; dès le début, <span class=\"kw-chiffre\">3-5 jours</span> max.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Corticoïdes</strong></span></td>\n            <td>Per os <span class=\"kw-chiffre\">3-5 jours</span> (tolérance globale &gt; <span class=\"kw-ttt\">AINS</span>) — prudence si <span class=\"kw-ci\">diabète</span> ou <span class=\"kw-ci\">HTA déséquilibrés</span> ; voie <strong>intra-articulaire</strong> si arthrite accessible.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Inhibiteurs de l'IL-1</strong></span></td>\n            <td>Réservés aux <strong>échecs / CI / <span class=\"kw-ci\">intolérance</span></strong> des précédents ; <span class=\"kw-ci\">contre-indiqués si infection</span> ; initiation hospitalière.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Mesures associées :</strong> <span class=\"kw-clinique\">repos</span> (orthèse), <span class=\"kw-clinique\">glaçage</span> articulaire (raccourcit l'accès), <span class=\"kw-ttt\">antalgiques</span>.</p>","frequence":0},{"id":"198-19","rang":"A","rubrique":"Prise en charge","titre":"Connaître les règles hygiénodiététiques et les principes des traitements hypouricémiants","contenu":"<p><strong><span class=\"kw-ttt\">Règles hygiéno-diététiques</span></strong> (seule mesure de l'hyperuricémie asymptomatique) :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Éviter — mnémo BAS</span> : <span class=\"kw-etio\">Bières</span> (même sans <span class=\"kw-etio\">alcool</span>), <span class=\"kw-etio\">Alcools forts</span>, <span class=\"kw-etio\">Sodas sucrés</span> / jus riches en fructose.</li>\n        <li><strong>Modérer</strong> : viande, produits de la mer.</li>\n        <li><span class=\"kw-clinique\">Encourager</span> : <span class=\"kw-clinique\">amaigrissement progressif</span>, <span class=\"kw-ttt\">laitages écrémés</span> (<strong>effet uricosurique</strong>).</li>\n        <li>Arrêt si possible d'un <span class=\"kw-ci\">diurétique</span> favorisant → remplacer par <span class=\"kw-ttt\">losartan</span> ou <span class=\"kw-ttt\">amlodipine</span> (seuls antihypertenseurs <strong>uricosuriques</strong>).</li>\n      </ul>\n\n      <p><strong>Traitement hypo-uricémiant (THU)</strong> :</p>\n      <ul>\n        <li><strong>Indication</strong> : dès que le diagnostic de goutte est posé (dès la 1ʳᵉ crise) — <span class=\"kw-ci\">PAS d'indication dans l'hyperuricémie asymptomatique</span>.</li>\n        <li><strong>Cible</strong> : <span class=\"kw-bio\">uricémie</span> <span class=\"kw-chiffre\">&lt; 300 µmol/L</span> (<span class=\"kw-chiffre\">50 mg/L</span>) chez tous <span class=\"kw-clinique\">les</span> goutteux.</li>\n        <li><strong>À vie</strong>, sans arrêt même en cas de crise ; <span class=\"kw-def\">surveillance</span> <span class=\"kw-bio\">uricémie + DFGe</span> <span class=\"kw-chiffre\">1 à 2 ×/an</span> une fois la cible atteinte.</li>\n      </ul>\n\n      <table >\n        <thead><tr><th>Molécule</th><th>À retenir</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Allopurinol</strong></span> (1ʳᵉ intention)</td>\n            <td><span class=\"kw-def\">Inhibiteur de la xanthine oxydase</span> ; débuter à dose faible et augmenter par paliers. <span class=\"kw-alerte\">Risque de toxidermie</span> (<span class=\"kw-alerte\">Lyell</span>, DRESS) dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 premiers mois</span> → <span class=\"kw-ci\">arrêt immédiat et définitif</span> à la moindre <span class=\"kw-clinique\">éruption</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Fébuxostat</strong></span> (alternative)</td>\n            <td>Inhibiteur de la xanthine oxydase non purinique ; utile si <span class=\"kw-chiffre\">DFGe 30-60</span> ou <span class=\"kw-ci\">intolérance</span>. <span class=\"kw-ci\">Prudence si maladie CV sévère</span> ; <span class=\"kw-ci\">allergie</span> croisée possible avec l'allopurinol.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Démarrage du THU.</strong> Risque de crise lors de la baisse d'<span class=\"kw-bio\">uricémie</span> → couverture par <span class=\"kw-ttt\">colchicine</span> quotidienne ≥ <span class=\"kw-chiffre\">6 mois</span> + augmentation <strong>progressive</strong> des doses.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":0},{"id":"198-20","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les formes sévères de goutte","contenu":"<p>Formes sévères, conséquences d'une goutte <strong>non traitée</strong> ou négligée :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Goutte tophacée</span> : <span class=\"kw-clinique\">tophus</span> multiples et <span class=\"kw-clinique\">déformants</span>, handicap fonctionnel.</li>\n        <li><span class=\"kw-clinique\">Arthropathie chronique destructrice</span> : <span class=\"kw-clinique\">douleurs mécaniques</span> émaillées de crises ; <span class=\"kw-imagerie\">géodes / encoches épiphysaires</span> avec <strong>conservation prolongée de l'interligne</strong>.</li>\n        <li><span class=\"kw-clinique\">Goutte polyarticulaire</span>.</li>\n        <li><span class=\"kw-clinique\">Lithiase urique bilatérale</span> : calculs <span class=\"kw-imagerie\">radiotransparents</span> (<span class=\"kw-chiffre\">350-500 UH</span>), favorisés par <span class=\"kw-bio\">pH urinaire bas</span> et faible <span class=\"kw-bio\">diurèse</span>.</li>\n        <li><span class=\"kw-alerte\">Néphropathie uratique</span> : dépôts d'urates dans la <span class=\"kw-clinique\">médulla rénale</span> → <span class=\"kw-alerte\">insuffisance rénale chronique</span> (aggravée par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">AINS</span>).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 265 — Lithiase urinaire · 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":0},{"id":"198-21","rang":"B","rubrique":"Etiologies","titre":"Connaître les deux principales affections associées aux dépôts de PPCa","contenu":"<div class=\"callout callout-warn\"><strong><span class=\"kw-clinique\">Les</span> deux affections à rechercher systématiquement</strong> devant une chondrocalcinose (surtout si <span class=\"kw-chiffre\">&lt; 50 ans</span> ou diffuse) :\n        <ul>\n          <li><strong>1.</strong> <span class=\"kw-etio\">Hémochromatose génétique</span> → <span class=\"kw-bio\">fer sérique + coefficient de saturation de la transferrine</span>.</li>\n          <li><strong>2.</strong> <span class=\"kw-etio\">Hyperparathyroïdie primitive</span> → <span class=\"kw-bio\">calcémie ± PTH</span>.</li>\n        </ul>\n      </div>\n\n      <p>Autres causes secondaires plus rares (moyen mnémo <strong>« 5 H »</strong>) :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Hypophosphatasie</span> <span class=\"kw-etio\">congénitale</span> (<span class=\"kw-bio\">phosphatases alcalines basses</span>).</li>\n        <li><span class=\"kw-etio\">Hypomagnésémie</span> (<span class=\"kw-clinique\">syndrome de Gitelman</span>, <span class=\"kw-bio\">magnésémie</span> abaissée).</li>\n        <li><span class=\"kw-etio\">Hypothyroïdie</span>.</li>\n        <li>Autres : <span class=\"kw-etio\">ochronose</span>, <span class=\"kw-etio\">maladie de Wilson</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><span class=\"kw-clinique\">Les</span> <strong>formes primitives</strong> (liées à l'âge) restent les plus fréquentes ; les formes familiales sont diffuses et sévères, à évoquer chez le sujet <span class=\"kw-chiffre\">&lt; 50 ans</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 219 — Pathologie du fer · 268 — Hypercalcémie</em></p>","frequence":1},{"id":"198-22","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de traitement d’un accès aigu à cristaux de pyrophosphate de calcium","contenu":"<div class=\"callout callout-danger\"><strong>Différence majeure avec la goutte.</strong> La <span class=\"kw-alerte\">chondrocalcinose ne se guérit pas</span> : on ne sait pas dissoudre <span class=\"kw-clinique\">les</span> cristaux de PPC. La prise en charge est <strong>symptomatique</strong> (traitement des accès aigus), il n'y a <span class=\"kw-ci\">pas de traitement de fond dissolvant</span>.</div>\n\n      <p>L'<span class=\"kw-clinique\">accès aigu à PPC</span> se traite <strong>comme un accès goutteux</strong> :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Colchicine</span> : même protocole que la <span class=\"kw-def\">goutte</span> (espacée / réduite si <span class=\"kw-etio\">insuffisance rénale</span>).</li>\n        <li><span class=\"kw-ttt\">AINS</span> : à <strong>éviter ou réduire</strong> (durée la plus courte) chez ces <span class=\"kw-etio\">patients âgés</span>.</li>\n        <li><span class=\"kw-ttt\">Infiltration cortisonique</span> : solution simple si <span class=\"kw-clinique\">monoarthrite</span>, <strong>après avoir exclu une <span class=\"kw-alerte\">infection</span></strong> (<span class=\"kw-ttt\">ponction</span>).</li>\n        <li><span class=\"kw-ttt\">Anti-IL-1</span> : si crise <span class=\"kw-clinique\">réfractaire</span> ou <span class=\"kw-ci\">CI / intolérance</span> des autres traitements.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Prudence.</strong> Emploi prudent de <span class=\"kw-ttt\">colchicine</span> et <span class=\"kw-ttt\">AINS</span> du fait de l'<span class=\"kw-etio\">âge élevé</span>, des <span class=\"kw-etio\">comorbidités</span> et du risque d'<span class=\"kw-ci\">interactions médicamenteuses</span>.</div>","frequence":0},{"id":"198-23","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de traitement d’un accès aigu à cristaux d’hydroxyapatite","contenu":"<div class=\"callout callout-info\"><strong>Contexte.</strong> Crise très douloureuse, fréquente à l'<span class=\"kw-clinique\">épaule</span> (<span class=\"kw-clinique\">tendinite calcifiante de la coiffe</span>), par <span class=\"kw-def\">résorption aiguë spontanée</span> de la <span class=\"kw-imagerie\">calcification</span>. L'<strong><span class=\"kw-clinique\">évolution</span> spontanée favorable est la règle</strong>. Forme typique : <span class=\"kw-clinique\">épaule hyperalgique « intouchable »</span>.</div>\n\n      <ul>\n        <li><span class=\"kw-clinique\">Repos</span>, <span class=\"kw-clinique\">glaçage</span>.</li>\n        <li><span class=\"kw-ttt\">AINS</span>, voire <span class=\"kw-ttt\">corticothérapie orale</span> en cure courte (<span class=\"kw-chiffre\">3-5 jours</span>).</li>\n        <li><span class=\"kw-ttt\">Injections cortisoniques locales</span> : efficaces mais en <strong>2ᵉ intention</strong> (l'<span class=\"kw-clinique\">évolution</span> spontanée est favorable).</li>\n        <li><span class=\"kw-ttt\">Colchicine</span> : <strong>moins d'intérêt</strong> que dans <span class=\"kw-clinique\">les</span> autres rhumatismes microcristallins.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Au moindre doute</strong> sur une <span class=\"kw-alerte\">arthrite septique</span> (<span class=\"kw-clinique\">fièvre</span>, épanchement abondant), réaliser une <span class=\"kw-ttt\">ponction</span> articulaire. <span class=\"kw-clinique\">Les</span> cristaux d'apatite étant <span class=\"kw-alerte\">submicroscopiques</span>, on ne les recherche pas en pratique au microscope.</div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/hydroxyapatite-deposition-disease","label":"Radiopaedia : Hydroxyapatite deposition disease"}]}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Urgence</span> diagnostique :</strong> tout accès aigu fébrile doit faire éliminer une <span class=\"kw-alerte\">arthrite septique</span> (principal <span class=\"kw-etio\">diagnostic différentiel</span>)<br><strong>1er geste :</strong> <span class=\"kw-ttt\">ponction articulaire</span> avec analyse du <span class=\"kw-bio\">liquide synovial</span> (examen <span class=\"kw-bio\">bactériologique</span> systématique + recherche de <span class=\"kw-bio\">microcristaux</span>)<br><strong>Fenêtre thérapeutique :</strong> dans la goutte, débuter la <span class=\"kw-ttt\">colchicine</span> le plus tôt possible, idéalement <span class=\"kw-chiffre\">< 12h</span></p>","hospit":"<p><strong>Ambulatoire :</strong> la majorité des accès microcristallins se gèrent en <span class=\"kw-ttt\">ambulatoire</span><br><strong>Avis rhumatologue (goutte) :</strong> début <span class=\"kw-chiffre\">< 35 ans</span>, forme <span class=\"kw-clinique\">polyarticulaire</span> ou <span class=\"kw-clinique\">tophacée</span>/dactylite, <span class=\"kw-etio\">insuffisance rénale</span> (<span class=\"kw-chiffre\">DFGe < 60 ml/min</span>), <span class=\"kw-etio\">insuffisance cardiaque</span> ou coronaire instable, goutte difficile à traiter<br><strong>Avis rhumatologue (PPC) :</strong> chondrocalcinose chez sujet <span class=\"kw-chiffre\">< 50 ans</span> ou atteinte polyarticulaire pseudorhumatoïde<br><strong>Avis rhumatologue (apatite) :</strong> <span class=\"kw-clinique\">épaule douloureuse chronique</span> avec calcifications ou accès récidivants<br><strong>Avant fébuxostat :</strong> antécédent d'<span class=\"kw-ci\">allergie à l'allopurinol</span></p>","redflags":"<ul><li><span class=\"kw-clinique\">Fièvre</span>, <span class=\"kw-clinique\">frissons</span> : doivent faire craindre une <span class=\"kw-alerte\">arthrite septique</span> associée ou concomitante</li><li><span class=\"kw-bio\">Syndrome inflammatoire biologique</span> marqué (<span class=\"kw-bio\">CRP élevée</span>, <span class=\"kw-bio\">hyperleucocytose</span>) ne permet pas d'exclure une <span class=\"kw-alerte\">infection</span></li><li><span class=\"kw-clinique\">Épanchement articulaire</span> important (rhumatisme apatitique notamment) : doit faire évoquer un <span class=\"kw-alerte\">processus septique</span> et impose la <span class=\"kw-ttt\">ponction</span></li><li><span class=\"kw-etio\">Syndrome de la dent couronnée</span> : <span class=\"kw-clinique\">cervicalgie aiguë</span> fébrile avec limitation des rotations, à différencier d'une <span class=\"kw-alerte\">rachialgie infectieuse ou tumorale</span></li><li><span class=\"kw-clinique\">Épaule hyperalgique « intouchable »</span> (apatite) : examen quasi impossible, <span class=\"kw-ttt\">ponction</span> au moindre doute d'<span class=\"kw-alerte\">arthrite septique</span></li><li><span class=\"kw-etio\">Infection</span> ou <span class=\"kw-etio\">infarctus</span> : peuvent être la cause déclenchante d'un accès et doivent être recherchés</li></ul>","principes":"<p>Traiter l'<span class=\"kw-clinique\">accès aigu</span> par un <span class=\"kw-ttt\">anti-inflammatoire</span> précoce ; dans la <span class=\"kw-etio\">goutte</span>, y associer un <span class=\"kw-ttt\">traitement hypo-uricémiant</span> à vie et des <span class=\"kw-ttt\">mesures hygiéno-diététiques</span>.</p><p><strong>Accès aigu (goutte & PPC)</strong></p><p>PPC : mêmes traitements que la goutte mais emploi prudent (sujet âgé, <span class=\"kw-def\">comorbidités</span>), <span class=\"kw-ttt\">AINS</span> <span class=\"kw-ci\">à éviter</span> ou réduire.</p><ul><li><span class=\"kw-ttt\">Colchicine</span> à débuter dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">< 12h</span>, à <span class=\"kw-chiffre\">faible dose</span> (aussi efficace et moins toxique que les fortes doses)</li><li><span class=\"kw-ttt\">AINS</span> (<span class=\"kw-ttt\">naproxène</span>) dès le début, sur <span class=\"kw-chiffre\">3-5 jours</span> maximum</li><li><span class=\"kw-ttt\">Corticoïdes</span> per os <span class=\"kw-chiffre\">3-5 jours</span> (<span class=\"kw-ci\">déconseillés si diabète ou HTA déséquilibrés</span>) ou en <span class=\"kw-ttt\">intra-articulaire</span> si monoarthrite accessible (après exclusion d'une infection)</li><li><span class=\"kw-ttt\">Inhibiteurs de l'IL-1</span> réservés aux échecs/intolérances — <span class=\"kw-ci\">contre-indiqués en cas d'infection</span></li><li>Mesures associées : <span class=\"kw-ttt\">repos</span>, <span class=\"kw-ttt\">glaçage</span> avec protection cutanée, antalgiques</li></ul><p><strong>Traitement de fond de la goutte (THU)</strong></p><p>Allopurinol : arrêt immédiat et définitif au moindre signe de réaction cutanée (risque de toxidermie grave : Lyell, DRESS).</p><ul><li>Indiqué dès la <span class=\"kw-chiffre\">1ère crise</span> de goutte diagnostiquée ; <span class=\"kw-ci\">non indiqué dans l'hyperuricémie asymptomatique</span></li><li><span class=\"kw-ttt\">Allopurinol</span> (inhibiteur de la xanthine oxydase) en 1ère intention si <span class=\"kw-chiffre\">DFGe > 60</span></li><li><span class=\"kw-ttt\">Fébuxostat</span> si <span class=\"kw-chiffre\">DFGe = 30</span> ou alternative — <span class=\"kw-ci\">prudence si maladie cardiovasculaire sévère</span></li><li>Cible : <span class=\"kw-bio\">uricémie</span> <span class=\"kw-chiffre\">< 300 µmol/L (50 mg/L)</span></li><li>Débuter à dose <span class=\"kw-chiffre\">progressive</span> + <span class=\"kw-ttt\">colchicine</span> ≥ <span class=\"kw-chiffre\">6 mois</span> (prévention des crises d'instauration)</li><li>Traitement <span class=\"kw-chiffre\">à vie</span>, jamais arrêté même pendant une crise</li></ul><p><strong>Mesures hygiéno-diététiques (goutte)</strong></p><ul><li>Frein sur les <span class=\"kw-ttt\">BAS</span> : <span class=\"kw-ttt\">Bières</span> (même sans alcool), <span class=\"kw-ttt\">Alcools forts</span>, <span class=\"kw-ttt\">Sodas sucrés</span> riches en fructose</li><li>Modération de la viande et des produits de la mer</li><li>Encourager l'<span class=\"kw-ttt\">amaigrissement progressif</span> et les <span class=\"kw-ttt\">laitages écrémés</span> (effet uricosurique)</li><li>Remplacer un diurétique favorisant par <span class=\"kw-ttt\">losartan</span> ou <span class=\"kw-ttt\">amlodipine</span> (antihypertenseurs uricosuriques)</li></ul><p><strong>Rhumatisme apatitique</strong></p><ul><li>Évolution spontanément favorable (résorption) : <span class=\"kw-ttt\">repos</span>, <span class=\"kw-ttt\">glaçage</span></li><li><span class=\"kw-ttt\">AINS</span> ou <span class=\"kw-ttt\">corticothérapie</span> orale en cure courte <span class=\"kw-chiffre\">3-5 jours</span></li><li><span class=\"kw-ttt\">Injections cortisoniques locales</span> efficaces mais en 2e intention</li><li><span class=\"kw-ttt\">Colchicine</span> de moindre intérêt que dans les autres rhumatismes microcristallins</li></ul>","suivi":"<p><strong>Goutte (THU) :</strong> contrôler <span class=\"kw-bio\">uricémie</span> + <span class=\"kw-bio\">DFGe</span> avant traitement puis <span class=\"kw-chiffre\">1 à 2x/an</span> une fois la <span class=\"kw-chiffre\">cible < 300 µmol/L</span> atteinte<br><strong>Allopurinol :</strong> surveiller la survenue de <span class=\"kw-clinique\">réactions cutanées</span> les <span class=\"kw-chiffre\">3 premiers mois</span> (arrêt immédiat même si éruption minime)<br><strong>Fébuxostat :</strong> surveiller <span class=\"kw-bio\">tests hépatiques</span> et <span class=\"kw-bio\">fonction thyroïdienne</span><br><strong>Uricémie en crise :</strong> peut être normale en accès → recontrôler une <span class=\"kw-chiffre\">quinzaine de jours</span> après<br><strong>Dépistage associé :</strong> <span class=\"kw-etio\">facteurs de risque cardiovasculaires</span>, <span class=\"kw-etio\">syndrome métabolique</span>, <span class=\"kw-etio\">insuffisance rénale</span></p>"},"liensGlobaux":[{"href":"https://www.lecofer.org/item-cours-1-19-0.php","label":"Collège (COFER) — cours arthropathies microcristallines"},{"href":"https://radiopaedia.org/articles/crystal-arthropathy","label":"Radiopaedia : Crystal arthropathy (vue d'ensemble)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Accès articulaire aigu <span class=\"kw-etio\">inflammatoire</span> — Début brutal, maximum des symptômes <span class=\"kw-chiffre\">< 24</span>h, rougeur « rouge pivoine », douleur ≥ 7/10","detail":"<h4>CAT — Accès articulaire aigu microcristallin — Exclure une arthrite septique puis identifier le microcristal en cause</h4>","branches":[{"to":"q-bacterio","label":"Ponction articulaire systématique","color":"blue"}]},{"id":"q-bacterio","kind":"decision","label":"Ponction articulaire : examen bactériologique du liquide synovial — Microcristaux recherchés sur tout liquide d'arthrite indifférenciée ou récidivante","branches":[{"to":"t-septique","label":"Bactériologie positive ou doute d'infection","color":"red"},{"to":"q-orientation","label":"Bactériologie négative + microcristaux","color":"green"}]},{"id":"t-septique","kind":"terminal","label":"Arthrite septique non exclue — urgence — Principal diagnostic différentiel","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Urgence</span> : ne pas conclure à un accès microcristallin</li><li>Prise en charge d'une <span class=\"kw-alerte\">arthrite septique</span> (passage aux urgences, <span class=\"kw-alerte\">hospitalisation</span>)</li><li>Une <span class=\"kw-etio\">infection</span> peut aussi être la cause déclenchante d'un accès microcristallin associé</li></ul>"},{"id":"q-orientation","kind":"decision","label":"Orientation selon cristaux, terrain et localisation — Bactériologie négative + arguments microcristallins","branches":[{"to":"t-goutte","label":"UMS · gros orteil · homme > 35 ans","color":"amber"},{"to":"t-ppc","label":"PPC · genou/poignet · > 60 ans","color":"amber"},{"to":"t-apatite","label":"Calcification péri-articulaire · épaule · femme 30-50 ans","color":"amber"}]},{"id":"t-goutte","kind":"terminal","label":"Goutte — Cristaux d'urate de sodium (UMS)","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Métatarso-phalangienne du gros orteil</span>, membre inférieur, <span class=\"kw-etio\">homme > 35 ans</span> en surpoids</li><li><span class=\"kw-bio\">Microcristaux d'UMS</span> fins, en aiguille, fortement biréfringents (pathognomonique)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Colchicine</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">< 12h</span> à <span class=\"kw-chiffre\">faible dose</span> ; <span class=\"kw-ttt\">AINS</span> (<span class=\"kw-ttt\">naproxène</span>) ou <span class=\"kw-ttt\">corticoïdes</span> <span class=\"kw-chiffre\">3-5 jours</span></li><li><span class=\"kw-ttt\">Inhibiteurs de l'IL-1</span> si échec/intolérance — <span class=\"kw-ci\">CI si infection</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Traitement hypo-uricémiant</span> dès la <span class=\"kw-chiffre\">1ère crise</span> : <span class=\"kw-ttt\">allopurinol</span> si <span class=\"kw-chiffre\">DFGe > 60</span>, <span class=\"kw-ttt\">fébuxostat</span> si <span class=\"kw-chiffre\">DFGe bas</span></li><li>Cible <span class=\"kw-bio\">uricémie</span> <span class=\"kw-chiffre\">< 300 µmol/L</span>, à vie ; <span class=\"kw-ttt\">mesures hygiéno-diététiques</span> (BAS) + <span class=\"kw-ttt\">colchicine</span> ≥ <span class=\"kw-chiffre\">6 mois</span> à l'instauration</li></ul>"},{"id":"t-ppc","kind":"terminal","label":"Rhumatisme à PPC (chondrocalcinose) — Cristaux de pyrophosphate de calcium","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Genou</span>, <span class=\"kw-clinique\">poignet</span>, <span class=\"kw-etio\">sujet > 60 ans</span> ; <span class=\"kw-radio\">calcifications</span> caractéristiques à la <span class=\"kw-imagerie\">radiographie</span></li><li><span class=\"kw-bio\">Cristaux de PPC</span> carrés/rectangulaires, peu ou pas biréfringents</li></ul><h4>Traitement</h4><ul><li>Prise en charge <span class=\"kw-ttt\">symptomatique</span> (la <span class=\"kw-etio\">chondrocalcinose</span> ne se guérit pas)</li><li><span class=\"kw-ttt\">Colchicine</span>/<span class=\"kw-ttt\">AINS</span> prudents (sujet âgé), <span class=\"kw-ttt\">infiltration cortisonique</span> si monoarthrite</li></ul><h4>Conduite</h4><ul><li>Si <span class=\"kw-chiffre\">< 50 ans</span> : rechercher une forme secondaire — <span class=\"kw-etio\">hémochromatose</span> (<span class=\"kw-bio\">fer + CST</span>), <span class=\"kw-etio\">hyperparathyroïdie primitive</span> (<span class=\"kw-bio\">calcémie ± PTH</span>)</li></ul>"},{"id":"t-apatite","kind":"terminal","label":"Rhumatisme apatitique — Cristaux d'apatite non visibles en microscopie","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Épaule</span> (tendinite calcifiante de la coiffe), <span class=\"kw-etio\">femme 30-50 ans</span></li><li><span class=\"kw-radio\">Calcifications péri-articulaires</span> ; <span class=\"kw-clinique\">évolution</span> spontanément favorable</li><li>Cristaux trop petits pour la microscopie optique → pas de recherche dans le liquide</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Repos</span>, <span class=\"kw-ttt\">glaçage</span>, <span class=\"kw-ttt\">AINS</span> ou <span class=\"kw-ttt\">corticothérapie</span> courte <span class=\"kw-chiffre\">3-5 jours</span></li><li><span class=\"kw-ttt\">Injection cortisonique locale</span> en <span class=\"kw-chiffre\">2e intention</span> ; <span class=\"kw-ttt\">colchicine</span> de moindre intérêt</li></ul>"}]},"cards":[{"i":"0bd62c42cbf2","n":198,"o":"198-1","u":"Définition","t":"Connaître les trois principaux microcristaux impliqués en pathologie humaine","q":"Quels sont les trois principaux microcristaux impliqués dans les arthropathies microcristallines humaines ?","a":"Les trois principaux microcristaux sont :\n<ul>\n<li>L'<strong>urate monosodique</strong> (UMS) ou urate de sodium.</li>\n<li>Le <strong>pyrophosphate de calcium</strong> (PPC), ou cristal calcique.</li>\n<li>Le <strong>phosphate de calcium</strong> / <strong>apatite</strong>, également un cristal calcique.</li>\n</ul>"},{"i":"3b5b93b28e82","n":198,"o":"198-1","u":"Définition","t":"Connaître les trois principaux microcristaux impliqués en pathologie humaine","q":"Quelle arthropathie est associée aux cristaux d'urate monosodique (UMS) et quelle est sa population typique ?","a":"Les cristaux d'<strong>urate monosodique</strong> (UMS) sont associés à la <strong>goutte</strong>. Le terrain typique est un <strong>homme de plus de 35 ans</strong>, souvent en situation de <strong>surpoids</strong>."},{"i":"56a81c21e9fb","n":198,"o":"198-1","u":"Définition","t":"Connaître les trois principaux microcristaux impliqués en pathologie humaine","q":"Quelle arthropathie est associée aux cristaux de pyrophosphate de calcium (PPC) et quelle est sa population typique ?","a":"Les cristaux de <strong>pyrophosphate de calcium</strong> (PPC) sont associés à la <strong>chondrocalcinose</strong> (parfois appelée pseudo-goutte). La population typique est le <strong>sujet âgé</strong>, avec une prédominance féminine."},{"i":"75722b8e17f0","n":198,"o":"198-1","u":"Définition","t":"Connaître les trois principaux microcristaux impliqués en pathologie humaine","q":"Quel est le piège classique concernant la nature des cristaux de la goutte ?","a":"Le piège à éviter est de penser que la goutte est due à des cristaux d'<strong>acide urique</strong>. Il faut retenir que les cristaux de la goutte sont de l'<strong>urate de sodium</strong> (ou urate monosodique) et que les cristaux d'acide urique n'existent que dans les voies urinaires, jamais dans l'articulation."},{"i":"8e0038d11552","n":198,"o":"198-1","u":"Définition","t":"Connaître les trois principaux microcristaux impliqués en pathologie humaine","q":"Quelle arthropathie est associée aux cristaux de phosphate de calcium / apatite et quelle est sa population typique ?","a":"Les cristaux de <strong>phosphate de calcium / apatite</strong> sont associés au <strong>rhumatisme apatitique</strong>. La population typique est la <strong>femme jeune</strong> (30-50 ans). Les dépôts d'apatite sont habituellement <strong>péri-articulaires</strong> et <strong>radio-opaques</strong>."},{"i":"048c5eedf024","n":198,"o":"198-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une crise de goutte et d’identification des situations nécessitant un avis spécialisé","q":"Quelle est l'utilité de l'uricémie plasmatique dans le diagnostic d'une crise de goutte aiguë ?","a":"<p>Une uricémie <strong>supérieure à 360 µmol/L</strong> est un argument en faveur du diagnostic. Cependant, l'uricémie <strong>peut être normale</strong> pendant l'accès aigu, une nouvelle mesure est alors recommandée environ <strong>15 jours après</strong> la crise.</p>"},{"i":"1b1d3bdeecf4","n":198,"o":"198-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une crise de goutte et d’identification des situations nécessitant un avis spécialisé","q":"Dans quelles situations un avis spécialisé en rhumatologie est-il recommandé pour la prise en charge d'une goutte ?","a":"<ul><li>Goutte précoce (<strong>< 35 ans</strong>) pour rechercher une maladie génétique ou rénale sous-jacente.</li><li>Goutte <strong>polyarticulaire</strong>, <strong>tophacée</strong> ou avec <strong>dactylite</strong>.</li><li>Goutte sur <strong>insuffisance rénale chronique</strong> (DFGe < 60 mL/min).</li><li>Goutte sur <strong>insuffisance cardiaque</strong> ou <strong>coronaire instable</strong>.</li><li>Goutte <strong>difficile à traiter</strong> (inefficacité, intolérance ou contre-indication à la colchicine, aux AINS ou aux corticoïdes).</li><li>Antécédent d'<strong>allergie à l'allopurinol</strong> avant la mise en route du fébuxostat.</li></ul>"},{"i":"5ea6a0331211","n":198,"o":"198-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une crise de goutte et d’identification des situations nécessitant un avis spécialisé","q":"Quels sont les arguments cliniques évocateurs d'une crise de goutte aiguë ?","a":"<ul><li>Un <strong>terrain évocateur</strong> (homme, âge moyen-avancé, facteurs de risque métaboliques).</li><li>Un accès aigu typique unilatéral: <ul><li><strong>rougeur pivoine</strong>.</li><li>oedème et douleur intenses.</li><li>installation rapide (pic symptomatique en <strong>< 24 heures</strong>).</li><li>localisation préférentielle au niveau de la <strong>première articulation métatarso-phalangienne</strong> (MTP du gros orteil).</li></ul></li></ul>"},{"i":"ed2ddccecfb7","n":198,"o":"198-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une crise de goutte et d’identification des situations nécessitant un avis spécialisé","q":"Quel est l'examen diagnostique de référence et pathognomonique d'une crise de goutte ?","a":"<p>L'examen diagnostique de référence est la mise en évidence de <strong>microcristaux d'urate monosodique</strong> (UMS) dans le <strong>liquide articulaire</strong> ou dans un <strong>tophus</strong>.</p>"},{"i":"f47f25fcf123","n":198,"o":"198-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une crise de goutte et d’identification des situations nécessitant un avis spécialisé","q":"Quel est le signe échographique caractéristique de la goutte et son intérêt diagnostique ?","a":"<p>Le signe échographique caractéristique est le signe du <strong>« double contour »</strong>. Il est utile au diagnostic et participe à la classification <strong>EULAR/ACR</strong> de la goutte.</p>"},{"i":"7dd7f4fc602d","n":198,"o":"198-11","u":"Identifier une urgence","t":"Connaître les modalités d’exclusion d’une une arthrite septique","q":"Quelle est l'entité pathologique à éliminer en priorité face à un accès microcristallin, et pourquoi est-ce une urgence ?","a":"<p>Il faut éliminer en priorité une <strong>arthrite septique</strong>. C'est une urgence car elle peut entraîner des destructions articulaires rapides et une infection systémique grave si elle n'est pas traitée rapidement.</p>"},{"i":"8606701fbe85","n":198,"o":"198-11","u":"Identifier une urgence","t":"Connaître les modalités d’exclusion d’une une arthrite septique","q":"Comment exclure une arthrite septique chez un patient présentant des signes évocateurs d'arthrite microcristalline ?","a":"<p>L'exclusion d'une arthrite septique repose sur la réalisation d'une <strong>ponction articulaire</strong> avec un <strong>examen bactériologique systématique du liquide synovial</strong>. Le diagnostic d'arthrite microcristalline sera retenu si des <strong>microcristaux sont identifiés</strong> ET que la <strong>bactériologie est négative</strong>.</p>"},{"i":"9cb7449dde4f","n":198,"o":"198-11","u":"Identifier une urgence","t":"Connaître les modalités d’exclusion d’une une arthrite septique","q":"Une arthrite microcristalline et une infection peuvent-elles coexister dans la même articulation ?","a":"<p>Oui, une association est possible. Une infection est même un <strong>facteur déclenchant classique</strong> d'accès de goutte ou de pseudo-goutte. La présence de cristaux n'exclut donc pas une surinfection bactérienne.</p>"},{"i":"f4dec005df5f","n":198,"o":"198-11","u":"Identifier une urgence","t":"Connaître les modalités d’exclusion d’une une arthrite septique","q":"Pourquoi un accès microcristallin peut-il être confondu avec une arthrite septique ?","a":"<p>L'inflammation cristalline peut provoquer des signes mimant une infection :</p><ul><li><strong>Fièvre</strong>, parfois associée à des frissons.</li><li>Présence d'un <strong>syndrome inflammatoire biologique</strong> (CRP très élevée, VS augmentée, hyperleucocytose).</li></ul><p>Ces manifestations peuvent faire évoquer à tort une arthrite septique, un abcès ou une cellulite infectieuse.</p>"},{"i":"0c599663a6e8","n":198,"o":"198-14","u":"Contenu multimédia","t":"Photographie d’un tophus cliniquement décelable (typique)","q":"Quelle est la composition histologique d'un tophus et ses complications potentielles ?","a":"<p>Un tophus est un amas de <strong>cristaux d'urate monosodique (UMS)</strong> cerclé d'une <strong>couronne cellulaire inflammatoire</strong>, lui conférant un aspect pseudo-granulomateux. Il peut s'<strong>enflammer</strong>, s'<strong>aboucher à la peau</strong> en laissant sourdre un liquide crayeux, et entraîner un <strong>handicap fonctionnel</strong> par les déformations qu'il provoque.</p>"},{"i":"99f97c3df96b","n":198,"o":"198-14","u":"Contenu multimédia","t":"Photographie d’un tophus cliniquement décelable (typique)","q":"Comment décrire l'aspect typique d'un tophus cliniquement décelable ?","a":"<p>Un tophus se présente comme un <strong>nodule sous-cutané ferme</strong>, d'aspect <strong>chamois ou crayeux par transparence</strong>.</p>"},{"i":"d4a0b59e51be","n":198,"o":"198-14","u":"Contenu multimédia","t":"Photographie d’un tophus cliniquement décelable (typique)","q":"Quelles sont les localisations typiques des tophus dans la goutte ?","a":"<ul><li>Le <strong>pavillon ou l'hélix de l'oreille</strong>.</li><li>Le <strong>coude</strong>, notamment la bursite olécrânienne.</li><li>Les <strong>tendons</strong> (calcanéen, patellaire).</li><li>Les <strong>articulations interphalangiennes distales (IPD)</strong> ou la pulpe des doigts (surtout chez les patients sous diurétiques).</li><li>Autour des <strong>articulations</strong> précédemment atteintes.</li></ul>"},{"i":"22b7de966b66","n":198,"o":"198-15","u":"Examens complémentaires","t":"Connaître les deux examens biologiques indispensables à visée diagnostique dans la goutte","q":"Quel est le premier examen biologique indispensable à visée diagnostique dans la goutte ?","a":"<p>Le premier examen est le dosage de l'<strong>uricémie</strong>.</p>"},{"i":"8852a4e998bc","n":198,"o":"198-15","u":"Examens complémentaires","t":"Connaître les deux examens biologiques indispensables à visée diagnostique dans la goutte","q":"Quelle est la valeur seuil de l'hyperuricémie dans le diagnostic de la goutte et quelle particularité faut-il connaître en période de crise ?","a":"<p>Une <strong>hyperuricémie</strong> est définie par une concentration > <strong>360 µmol/L (60 mg/L)</strong>. Il est important de noter que l'uricémie peut être <strong>normale en période de crise</strong> de goutte, nécessitant un recontrôle à <strong>15 jours</strong> si le diagnostic est suspecté.</p>"},{"i":"ca4a9a9925c1","n":198,"o":"198-15","u":"Examens complémentaires","t":"Connaître les deux examens biologiques indispensables à visée diagnostique dans la goutte","q":"Quel est le deuxième examen biologique indispensable à visée diagnostique dans la goutte et quels en sont les éléments pathognomoniques ?","a":"<p>Le deuxième examen est l'<strong>analyse du liquide articulaire</strong>. Elle vise à mettre en évidence les <strong>microcristaux d'urates de sodium (UMS)</strong>, ce qui est <strong>pathognomonique</strong> de la goutte. Le liquide est par ailleurs de type <strong>inflammatoire</strong> et la bactériologie doit être <strong>négative</strong>.</p>"},{"i":"680964e4210f","n":198,"o":"198-18","u":"Prise en charge","t":"Connaître les principes de prise en charge d’une crise aiguë de goutte","q":"Quels sont les principaux traitements pharmacologiques d'une crise aiguë de goutte, et leurs modalités d'utilisation ou précautions ?","a":"<p>Les principaux traitements sont :</p><ul><li>La <strong>colchicine</strong> : à initier idéalement &lt; 12h avec des <strong>faibles doses</strong> (aussi efficaces et moins toxiques que les fortes doses).</li><li>Les <strong>AINS</strong> : le <strong>naproxène per os</strong> est privilégié pour son meilleur profil cardiovasculaire. Utilisation courte (3-5 jours max) dès le début.</li><li>Les <strong>corticoïdes</strong> : par voie orale pendant 3-5 jours (meilleure tolérance globale que les AINS), ou en intra-articulaire si l'arthrite est accessible. Prudence si diabète ou HTA déséquilibrés.</li><li>Les <strong>inhibiteurs de l'IL-1</strong> : réservés aux échecs, CI ou intolérances des traitements précédents, en initiation hospitalière. Contre-indiqués en cas d'infection.</li></ul>"},{"i":"b3e8fd5fc661","n":198,"o":"198-18","u":"Prise en charge","t":"Connaître les principes de prise en charge d’une crise aiguë de goutte","q":"Quel est le principe fondamental de la prise en charge d'une crise aiguë de goutte ?","a":"<p>Le principe fondamental est de prendre en charge la crise le <strong>plus tôt possible</strong>, idéalement dans les <strong>12 premières heures</strong>.</p>"},{"i":"c0635c672421","n":198,"o":"198-18","u":"Prise en charge","t":"Connaître les principes de prise en charge d’une crise aiguë de goutte","q":"Quelles sont les mesures associées recommandées dans la prise en charge d'une crise aiguë de goutte ?","a":"<p>Les mesures associées comprennent :</p><ul><li>Le <strong>repos</strong> de l'articulation (avec une orthèse si nécessaire).</li><li>Le <strong>glaçage articulaire</strong>, qui peut raccourcir la durée de la crise.</li><li>Des <strong>antalgiques</strong> pour soulager la douleur.</li></ul>"},{"i":"c22130a2e2a8","n":198,"o":"198-18","u":"Prise en charge","t":"Connaître les principes de prise en charge d’une crise aiguë de goutte","q":"Sur quels critères le choix du traitement d'une crise aiguë de goutte est-il adapté ?","a":"<p>Le choix du traitement dépend :</p><ul><li>Des <strong>comorbidités</strong> (cardiovasculaires, diabète, ulcère, infection, DFG < 60 ml/min).</li><li>Des <strong>interactions médicamenteuses</strong>.</li><li>Du <strong>nombre d'articulations</strong> atteintes.</li></ul>"},{"i":"14b8b2a14242","n":198,"o":"198-19","u":"Prise en charge","t":"Connaître les règles hygiénodiététiques et les principes des traitements hypouricémiants","q":"Quelles sont les principales règles hygiéno-diététiques à conseiller à un patient présentant une arthropathie microcristalline ?","a":"<p>Il faut recommander au patient d'éviter les aliments et boissons suivants (mnémo BAS) :</p><ul><li>Les <strong>Bières (même sans alcool)</strong>.</li><li>Les <strong>Alcools forts</strong>.</li><li>Les <strong>Sodas sucrés / jus riches en fructose</strong>.</li></ul><p>Il est également conseillé de modérer la consommation de viande et de produits de la mer, et d'encourager un <strong>amaigrissement progressif</strong> ainsi que la prise de <strong>laitages écrémés</strong> (qui ont un effet uricosurique).</p>"},{"i":"28cbd06ff945","n":198,"o":"198-19","u":"Prise en charge","t":"Connaître les règles hygiénodiététiques et les principes des traitements hypouricémiants","q":"Dans quels cas doit-on instaurer un traitement hypouricémiant (THU) pour la goutte, et quelle est la cible d'uricémie ?","a":"<p>Le traitement hypouricémiant (THU) est indiqué <strong>dès que le diagnostic de goutte est posé</strong>, c'est-à-dire <strong>dès la première crise</strong>. Il n'est <strong>PAS indiqué dans l'hyperuricémie asymptomatique</strong>.</p><p>L'objectif est d'atteindre une uricémie inférieure à <strong>300 µmol/L (50 mg/L)</strong> chez tous les patients goutteux, et ce, à vie.</p>"},{"i":"4038ed0ac390","n":198,"o":"198-19","u":"Prise en charge","t":"Connaître les règles hygiénodiététiques et les principes des traitements hypouricémiants","q":"Comment adapter la prescription d'un diurétique favorisant l'hyperuricémie chez un patient atteint de goutte ?","a":"<p>Il convient, si possible, d'<strong>arrêter le diurétique</strong> incriminé et de le remplacer par un antihypertenseur ayant un effet uricosurique, comme le <strong>losartan</strong> ou l'<strong>amlodipine</strong>.</p>"},{"i":"893b2efc8ea9","n":198,"o":"198-19","u":"Prise en charge","t":"Connaître les règles hygiénodiététiques et les principes des traitements hypouricémiants","q":"Quel traitement hypouricémiant peut-on utiliser en alternative à l'allopurinol, et quelles sont les précautions spécifiques à prendre ?","a":"<p>Le <strong>fébuxostat</strong> est une alternative à l'allopurinol, particulièrement utile en cas de <strong>DFG entre 30 et 60 ml/min</strong> ou d'intolérance à l'allopurinol.</p><p>Il faut être <strong>prudent en cas de maladie cardiovasculaire sévère</strong> et savoir qu'une allergie croisée avec l'allopurinol est possible.</p>"},{"i":"a2e528b5dc7a","n":198,"o":"198-19","u":"Prise en charge","t":"Connaître les règles hygiénodiététiques et les principes des traitements hypouricémiants","q":"Quelle mesure d'accompagnement est nécessaire lors du démarrage d'un traitement hypouricémiant pour éviter une complication spécifique ?","a":"<p>Lors du démarrage d'un traitement hypouricémiant, il existe un <strong>risque de crise de goutte aiguë</strong> dû à la baisse rapide de l'uricémie. Pour prévenir cela, une couverture par <strong>colchicine quotidienne</strong> est nécessaire pendant au moins <strong>6 mois</strong>, associée à une augmentation progressive des doses du traitement hypouricémiant.</p>"},{"i":"a517b232d0c4","n":198,"o":"198-19","u":"Prise en charge","t":"Connaître les règles hygiénodiététiques et les principes des traitements hypouricémiants","q":"Quel est le traitement hypouricémiant de première intention pour la goutte, et quelle précaution doit-on prendre lors de son initiation ?","a":"<p>L'<strong>allopurinol</strong> est le traitement hypouricémiant de première intention. Il doit être débuté à <strong>faible dose</strong> et augmenté par paliers.</p><p>Une surveillance étroite est nécessaire pendant les 3 premiers mois en raison du risque de <strong>toxidermies sévères (dont Lyell et DRESS)</strong>. En cas de la moindre éruption cutanée, l'arrêt doit être <strong>immédiat et définitif</strong>.</p>"},{"i":"0fc0b4a7431c","n":198,"o":"198-22","u":"Prise en charge","t":"Connaître les principes de traitement d’un accès aigu à cristaux de pyrophosphate de calcium","q":"Quels sont les traitements de première intention d'un accès aigu à cristaux de pyrophosphate de calcium ?","a":"<ul><li>La <strong>colchicine</strong>, avec le même protocole que pour la goutte, en adaptant la posologie si insuffisance rénale.</li><li>Les <strong>AINS</strong> (anti-inflammatoires non stéroïdiens), à utiliser avec prudence chez le sujet âgé en réduisant la durée de traitement.</li></ul>"},{"i":"550d08b1ad99","n":198,"o":"198-22","u":"Prise en charge","t":"Connaître les principes de traitement d’un accès aigu à cristaux de pyrophosphate de calcium","q":"Quelle est la principale différence de prise en charge entre la chondrocalcinose articulaire et la goutte ?","a":"<p>La chondrocalcinose ne se guérit pas car on ne sait pas dissoudre les <strong>cristaux de pyrophosphate de calcium (PPC)</strong>. La prise en charge est donc uniquement <strong>symptomatique</strong>, contrairement à la goutte où un traitement de fond est possible.</p>"},{"i":"916828472722","n":198,"o":"198-22","u":"Prise en charge","t":"Connaître les principes de traitement d’un accès aigu à cristaux de pyrophosphate de calcium","q":"Pourquoi doit-on être prudent lors de l'utilisation de colchicine et d'AINS dans le traitement de l'accès aigu à cristaux de pyrophosphate de calcium ?","a":"<p>La prudence s'impose en raison de l'âge souvent élevé des patients, de leurs <strong>comorbidités</strong> associées, et du risque important d'<strong>interactions médicamenteuses</strong>.</p>"},{"i":"ae67acff6c12","n":198,"o":"198-22","u":"Prise en charge","t":"Connaître les principes de traitement d’un accès aigu à cristaux de pyrophosphate de calcium","q":"Dans quelles situations l'infiltration cortisonique et les anti-IL-1 sont-ils utilisés pour traiter un accès aigu de chondrocalcinose ?","a":"<ul><li>L'<strong>infiltration cortisonique</strong> est une solution simple et efficace en cas de <strong>monoarthrite</strong>, après avoir exclu une infection articulaire par ponction.</li><li>Les <strong>anti-IL-1</strong> sont réservés aux <strong>crises réfractaires</strong> ou en cas de contre-indication ou intolérance aux autres traitements, à utiliser avec prudence.</li></ul>"},{"i":"24cf29190b21","n":198,"o":"198-8","u":"Diagnostic positif","t":"Connaître la description d’un accès aigu microcristallin","q":"Décrivez les signes locaux d'inflammation d'une articulation lors d'un accès aigu microcristallin.","a":"<p>L'articulation présente une <strong>inflammation locale forte</strong>, se manifestant par :</p><ul><li>Une <strong>rougeur</strong> caractéristique, souvent décrite comme « <strong>rouge pivoine</strong> »</li><li>Un <strong>gonflement</strong></li><li>Une <strong>chaleur</strong> locale</li></ul>"},{"i":"3e777f37cbef","n":198,"o":"198-8","u":"Diagnostic positif","t":"Connaître la description d’un accès aigu microcristallin","q":"Quelle est l'évolution spontanée d'un accès aigu microcristallin au début de la maladie ?","a":"<p>Au début de la maladie, l'accès aigu microcristallin évolue vers une <strong>résolution spontanée</strong> en quelques jours à semaines, avec une <strong>restauration ad integrum</strong> de l'articulation.</p>"},{"i":"44838bf94b21","n":198,"o":"198-8","u":"Diagnostic positif","t":"Connaître la description d’un accès aigu microcristallin","q":"Quelles sont les caractéristiques de la douleur lors d'un accès aigu microcristallin ?","a":"<p>La douleur est <strong>intense</strong>, avec une Échelle Visuelle Analogique (EVA) ou une Échelle Numérique (EN) généralement <strong>supérieure ou égale à 7/10</strong>.</p>"},{"i":"bbc10ee40493","n":198,"o":"198-8","u":"Diagnostic positif","t":"Connaître la description d’un accès aigu microcristallin","q":"Quels sont les signes généraux et biologiques pouvant accompagner un accès aigu microcristallin ?","a":"<p>L'inflammation peut s'accompagner de :</p><ul><li>Signes généraux : <strong>fièvre</strong>, voire <strong>frissons</strong></li><li>Signes biologiques : un <strong>syndrome inflammatoire</strong>, notamment une <strong>CRP élevée</strong> et une <strong>hyperleucocytose</strong>. Il est important d'éliminer une infection devant ces signes.</p></ul>"},{"i":"e39e204a51ec","n":198,"o":"198-8","u":"Diagnostic positif","t":"Connaître la description d’un accès aigu microcristallin","q":"Comment débute cliniquement un accès aigu microcristallin typique (goutte, PPC, apatite) ?","a":"<p>Un accès aigu microcristallin typique est caractérisé par un <strong>début brutal</strong>, avec un maximum des symptômes atteint en <strong>moins de 24 heures</strong>.</p>"}]};